import React from 'react';

export default function Timetable() {
  const schedule = [
    { time: '10:00', day: 'Mon', class: 'Math 101' },
    { time: '11:00', day: 'Wed', class: 'Science' },
    { time: '12:00', day: 'Thu', class: 'English Lit' },
    { time: '2:00', day: 'Fri', class: 'History' },
  ];

  return (
    <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
      <h3>Upcoming Class Schedule</h3>
      <table style={{ width: '100%', marginTop: '20px', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ textAlign: 'left', borderBottom: '1px solid #ddd' }}>
            <th style={{ padding: '10px' }}>Time</th>
            <th style={{ padding: '10px' }}>Day</th>
            <th style={{ padding: '10px' }}>Class</th>
          </tr>
        </thead>
        <tbody>
          {schedule.map((item, i) => (
            <tr key={i} style={{ borderBottom: '1px solid #f0f0f0' }}>
              <td style={{ padding: '10px' }}>{item.time}</td>
              <td style={{ padding: '10px' }}>{item.day}</td>
              <td style={{ padding: '10px', color: '#1976d2', fontWeight: 'bold' }}>{item.class}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
